//! Test support mirroring Calcpad.Tests/TestCalc.cs and the xunit assertions used by the
//! transcribed tests (generated by tools/transcribe_xunit.py).
#![allow(dead_code, non_snake_case)]

use std::cell::RefCell;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::rc::Rc;

use calcpad_core::parsers::expression_parser::ExpressionParser;
use calcpad_core::{MathParser, MathParserException, MathSettings};

/// `new()` MathSettings with C# object initializer style setters.
pub fn ms() -> MathSettings {
    MathSettings::default()
}

/// Integer settings take f64 because the transcriber writes numeric literals as doubles.
pub trait MsExt {
    fn Degrees(self, d: f64) -> Self;
    fn IsComplex(self, b: bool) -> Self;
    fn Decimals(self, d: f64) -> Self;
    fn Substitute(self, b: bool) -> Self;
    fn FormatEquations(self, b: bool) -> Self;
}

impl MsExt for MathSettings {
    fn Degrees(mut self, d: f64) -> Self {
        self.degrees = d as i32;
        self
    }
    fn IsComplex(mut self, b: bool) -> Self {
        self.is_complex = b;
        self
    }
    fn Decimals(mut self, d: f64) -> Self {
        self.set_decimals(d as i32);
        self
    }
    fn Substitute(mut self, b: bool) -> Self {
        self.substitute = b;
        self
    }
    fn FormatEquations(mut self, b: bool) -> Self {
        self.format_equations = b;
        self
    }
}

/// Port of Calcpad.Tests/TestCalc.cs. Errors are raised as panics carrying the
/// MathParserException, so `assert_throws` can catch them like `Assert.Throws`.
pub struct TestCalc {
    parser: MathParser,
}

fn raise(e: MathParserException) -> ! {
    eprintln!("calcpad error: {}", e.message);
    std::panic::panic_any(e)
}

impl TestCalc {
    pub fn new(settings: MathSettings) -> TestCalc {
        TestCalc {
            parser: MathParser::new(Rc::new(RefCell::new(settings))),
        }
    }

    /// `TestCalc.CompareWithTolerance(a, b, tolerance)`
    pub fn CompareWithTolerance(a: &str, b: &str, tolerance: &str) -> String {
        format!("r = abs({a} - {b}) \u{2264} {tolerance}*max(abs({a}); 1)")
    }

    pub fn CompareWithToleranceDirect(a: &str, b: &str, tolerance: &str) -> String {
        format!("abs({a} - {b}) \u{2264} {tolerance}*max(abs({a}); 1)")
    }

    /// `Run(string)` and `Run(string[])`
    pub fn Run<S: Expressions>(&mut self, expressions: S) -> f64 {
        for e in expressions.items() {
            if let Err(e) = self.parser.parse(&e, true) {
                raise(e);
            }
            if let Err(e) = self.parser.calculate(true, -1) {
                raise(e);
            }
        }
        self.parser.real()
    }

    pub fn RunAll<S: AsRef<str>>(&mut self, expressions: &[S]) -> f64 {
        let v: Vec<String> = expressions.iter().map(|x| x.as_ref().to_string()).collect();
        self.Run(v)
    }

    pub fn Real(&self) -> f64 {
        self.parser.real()
    }

    pub fn Imaginary(&self) -> f64 {
        self.parser.imaginary()
    }

    /// `TestCalc.Complex` as (re, im).
    pub fn Complex(&self) -> (f64, f64) {
        (self.parser.real(), self.parser.imaginary())
    }

    /// `TestCalc.ToString()` = `MathParser.ResultAsString`
    pub fn ToString(&self) -> String {
        self.parser.result_as_string()
    }
}

/// The argument of `TestCalc.Run`: one expression or an array of them.
pub trait Expressions {
    fn items(self) -> Vec<String>;
}

impl Expressions for &str {
    fn items(self) -> Vec<String> {
        vec![self.to_string()]
    }
}

impl Expressions for String {
    fn items(self) -> Vec<String> {
        vec![self]
    }
}

impl Expressions for &String {
    fn items(self) -> Vec<String> {
        vec![self.clone()]
    }
}

impl<const N: usize> Expressions for [&str; N] {
    fn items(self) -> Vec<String> {
        self.iter().map(|s| s.to_string()).collect()
    }
}

impl Expressions for Vec<String> {
    fn items(self) -> Vec<String> {
        self
    }
}

/// `new ExpressionParser { Settings = new Settings() }` followed by `Parse(source, true, false)`.
pub fn render(source: &str) -> String {
    let mut p = ExpressionParser::new();
    p.parse(source, true);
    p.html_result
}

// ----- xunit assertions ---------------------------------------------------------------

/// Equality as used by `Assert.Equal` for the argument types the tests use.
pub trait XEq<Rhs = Self> {
    fn x_eq(&self, other: &Rhs) -> bool;
}

impl XEq for f64 {
    /// `object.Equals(double, double)`: NaN equals NaN.
    fn x_eq(&self, other: &f64) -> bool {
        self == other || self.is_nan() && other.is_nan()
    }
}

impl XEq<String> for &str {
    fn x_eq(&self, other: &String) -> bool {
        *self == other.as_str()
    }
}

impl XEq<&str> for &str {
    fn x_eq(&self, other: &&str) -> bool {
        self == other
    }
}

/// `Assert.Equal(string, string)` with null strings.
impl XEq for Option<String> {
    fn x_eq(&self, other: &Option<String>) -> bool {
        self == other
    }
}

impl XEq for bool {
    fn x_eq(&self, other: &bool) -> bool {
        self == other
    }
}

impl XEq<String> for String {
    fn x_eq(&self, other: &String) -> bool {
        self == other
    }
}

/// `Assert.Equal(expected, actual)`
#[track_caller]
pub fn assert_equal<A: XEq<B> + std::fmt::Debug, B: std::fmt::Debug>(expected: A, actual: B) {
    assert!(
        expected.x_eq(&actual),
        "Assert.Equal() Failure\nExpected: {expected:?}\nActual:   {actual:?}"
    );
}

#[track_caller]
pub fn assert_equal_str(expected: &str, actual: &str) {
    assert_eq!(expected, actual, "Assert.Equal() Failure");
}

/// `Assert.Equal(double expected, double actual, double tolerance)`
#[track_caller]
pub fn assert_equal_tol(expected: f64, actual: f64, tolerance: f64) {
    assert!(!(tolerance.is_nan() || tolerance < 0.0), "invalid tolerance");
    let ok = expected.x_eq(&actual) || (expected - actual).abs() <= tolerance;
    assert!(ok, "Assert.Equal() Failure: Values are not within tolerance {tolerance:e}\nExpected: {expected:?}\nActual:   {actual:?}");
}

/// `Assert.InRange(actual, low, high)`
#[track_caller]
pub fn assert_in_range(actual: f64, low: f64, high: f64) {
    assert!(
        low <= actual && actual <= high,
        "Assert.InRange() Failure: {actual} not in [{low}, {high}]"
    );
}

/// `Assert.Contains(substring, actual)`
#[track_caller]
pub fn assert_contains(expected_substring: &str, actual: &str) {
    assert!(
        actual.contains(expected_substring),
        "Assert.Contains() Failure\nNot found: {expected_substring:?}\nIn value:  {actual:?}"
    );
}

/// `Assert.DoesNotContain(substring, actual)`
#[track_caller]
pub fn assert_does_not_contain(expected_substring: &str, actual: &str) {
    assert!(
        !actual.contains(expected_substring),
        "Assert.DoesNotContain() Failure\nFound: {expected_substring:?}\nIn value: {actual:?}"
    );
}

/// `Assert.Throws<MathParserException>(action)`
#[track_caller]
pub fn assert_throws<F: FnOnce()>(f: F) -> MathParserException {
    let prev = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let r = catch_unwind(AssertUnwindSafe(f));
    std::panic::set_hook(prev);
    match r {
        Ok(()) => panic!("Assert.Throws() Failure: No exception was thrown"),
        Err(payload) => match payload.downcast::<MathParserException>() {
            Ok(e) => {
                assert!(
                    !e.unexpected,
                    "Assert.Throws() Failure: a non MathParserException was thrown: {}",
                    e.message
                );
                *e
            }
            Err(p) => std::panic::resume_unwind(p),
        },
    }
}

/// `Assert.ThrowsAny<Exception>(...)`: passes when any exception (panic) is raised.
pub fn assert_throws_any<F: FnOnce()>(f: F) {
    let prev = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let r = catch_unwind(AssertUnwindSafe(f));
    std::panic::set_hook(prev);
    assert!(r.is_err(), "Assert.ThrowsAny() Failure: No exception was thrown");
}

